begin;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
update public.breeder_billing_prices set available=false where tier_code='HOBBY' and interval='year';
insert into auth.users(id,email,email_confirmed_at) values('e6102121-0000-4000-8000-000000000101','price-test@example.test',now());
insert into public.users(id,username,email,auth_user_id) values('price-test','pricetest','price-test@example.test','e6102121-0000-4000-8000-000000000101');
insert into public.breeder_billing_prices(id,tier_code,interval,amount_cents,stripe_product,stripe_price) values('e6102121-0000-4000-8000-000000000110','HOBBY','year',4900,'prod_test','price_notice_old');
create temp table campaign as select public.breeder_schedule_price('e6102121-0000-4000-8000-000000000110','price_notice_new',5900,now()+interval '60 days','e6102121-0000-4000-8000-000000000101') data;
select pg_temp.ok((select available from public.breeder_billing_prices where stripe_price='price_notice_old'),'old price stays available before start');
select pg_temp.ok(not (select available from public.breeder_billing_prices where stripe_price='price_notice_new'),'future price is unavailable before start');
select pg_temp.ok((select data->>'id' from campaign)=public.breeder_schedule_price('e6102121-0000-4000-8000-000000000110','price_notice_new',5900,now()+interval '60 days','e6102121-0000-4000-8000-000000000101')->>'id','campaign retry idempotent');
insert into public.breeder_billing_subscriptions(stripe_subscription,owner_id,offer_id,status,price_locked) values('sub_notice_regular','price-test','e6102121-0000-4000-8000-000000000110','active',false),('sub_notice_locked','price-test','e6102121-0000-4000-8000-000000000110','active',true);
select public.breeder_price_tick();
select public.breeder_price_tick();
select pg_temp.ok((select count(*)=1 from public.breeder_price_notices where stripe_subscription='sub_notice_regular'),'one durable notice on repeat tick');
select pg_temp.ok(not exists(select 1 from public.breeder_price_notices where stripe_subscription='sub_notice_locked'),'locked subscriber excluded');
update public.breeder_price_changes set starts_at=now()-interval '1 minute' where id=(select (data->>'id')::uuid from campaign);
select public.breeder_price_tick();
select pg_temp.ok((select available from public.breeder_billing_prices where stripe_price='price_notice_new'),'new price activated when due');
select pg_temp.ok(not (select available from public.breeder_billing_prices where stripe_price='price_notice_old'),'old price removed from new purchases');
select pg_temp.ok(not public.breeder_price_worker_authorized(repeat('0',64)),'forged cron token rejected');
set local role authenticated;
do $$begin
 begin perform * from public.breeder_price_notices;raise exception 'client read notices';exception when insufficient_privilege then null;end;
 begin perform public.breeder_price_tick();raise exception 'client activated price';exception when insufficient_privilege then null;end;
 begin perform public.breeder_price_worker_authorized('token');raise exception 'client checked token';exception when insufficient_privilege then null;end;
end$$;
reset role;
select 'price notice SQL checks passed' as result;
rollback;
